import json,subprocess,shutil
from html.parser import HTMLParser
from pathlib import Path
class Parser(HTMLParser):
 def __init__(self):
  super().__init__();self.scripts=[];self.current=None;self.svgs=0;self.tbody_rows=0;self.in_tbody=False
 def handle_starttag(self,tag,attrs):
  if tag=='script': self.current={'attrs':dict(attrs),'code':''}
  if tag=='svg': self.svgs+=1
  if tag=='tbody': self.in_tbody=True
  if tag=='tr' and self.in_tbody:self.tbody_rows+=1
 def handle_data(self,data):
  if self.current is not None:self.current['code']+=data
 def handle_endtag(self,tag):
  if tag=='script':self.scripts.append(self.current);self.current=None
  if tag=='tbody':self.in_tbody=False
p=Parser();p.feed(Path('output/contributions.html').read_text())
embedded=json.loads(next(s['code'] for s in p.scripts if s['attrs'].get('id')=='contribution-data'))
results=json.loads(Path('output/results.json').read_text())
assert embedded==results['tables']['store_channel_product']
assert p.tbody_rows==len(embedded) and p.svgs==2
js=next(s['code'] for s in p.scripts if s['attrs'].get('type')"'!='"'application/json')
