node=shutil.which('node')
checks={'embedded_json_equals_actual_results':True,'complete_combination_table_rows':p.tbody_rows,'default_static_svg_charts':p.svgs}
if node:
 r=subprocess.run([node,'--check','-'],input=js,text=True,capture_output=True)
 assert r.returncode==0,r.stderr
 checks['javascript_syntax']=True
 # Exercise actual HTML script with a minimal DOM; this is not a browser test.
 harness='''
