elements['contribution-data'].textContent=JSON.stringify(INPUT);
global.document={getElementById:key=>elements[key]};
'''.replace('INPUT',json.dumps(embedded,ensure_ascii=False))
 harness+=js
 harness+='''
let cases=0;
for(const st of ['',...new Set(facts.map(r=>r.selling_store_id))]){
 for(const ch of ['','线上商城','线下门店']){
  elements.store.value=st;elements.channel.value=ch;draw();
  const selected=facts.filter(r=>("'!st||r.selling_store_id===st)&&(!ch||r.channel===ch));
  const cents=selected.reduce((s,r)=>s+Math.round(r.change*100),0);
  assert(elements['"'selection-total'].textContent.includes(signed(cents/100)));
  const expectedProducts=new Set(selected.map(r=>r.product_id)).size;
  assert.equal((elements['product-chart'].innerHTML.match(/<rect /g)||[]).length,expectedProducts);
  assert("'!elements['"'product-chart'].innerHTML.includes('NaN'));cases++;
 }
}
process.stdout.write(String(cases));
'''
 r=subprocess.run([node,'-'],input=harness,text=True,capture_output=True)
 assert r.returncode==0,r.stderr
 checks['javascript_dom_stub_filter_cases_passed']=int(r.stdout)
else: checks['javascript_syntax']='not executed: node not installed'
Path('output/chart_validation.json').write_text(json.dumps(checks,ensure_ascii=False,indent=2)+'\\n')
print(json.dumps(checks,ensure_ascii=False,indent=2))
print('Files:',*[p.name for p in sorted(Path('output').iterdir())],sep='\\n')
